  id: string;
  clientId: string;
  serviceId: string;
  windowStart: string;
  windowEnd: string;
  createdAt: string;
}

interface Notification {
  id: string;
  clientId: string;
  kind: string;
  body: string;
  createdAt: string;
}

interface ServiceCount {
  serviceId: string;
  count: number;
}

interface StatsData {
  stats: {
    appointmentsTotal: number;
    appointmentsCancelled: number;
    occupancyRate: number;
    cancellationRate: number;
    topServicesByBookings: ServiceCount[];
    topServicesByCancellations: ServiceCount[];
  };
}

export default function DashboardPage() {
  const [appointments, setAppointments] = useState<Appointment[]>([]);
  const [waitlist, setWaitlist] = useState<WaitlistEntry[]>([]);
  const [notifications, setNotifications] = useState<Notification[]>([]);
  const [stats, setStats] = useState<StatsData | null>(null);
  const [isLoading, setIsLoading] = useState(true);
  const [timeOffset, setTimeOffset] = useState(0); // hours to advance
  const prevStatsRef = useRef<StatsData | null>(null);

  const fetchData = async () => {
    setIsLoading(true);
    try {
      const [apptsRes, waitRes, notifRes] = await Promise.all([
        fetch("/api/appointments"),
        fetch("/api/waitlist"),
        fetch("/api/notifications"),
      ]);

      if (apptsRes.ok) setAppointments(await apptsRes.json());
      if (waitRes.ok) setWaitlist(await waitRes.json());
      if (notifRes.ok) setNotifications(await notifRes.json());
    } catch (error) {
      console.error("Error fetching data:", error);
    } finally {
      setIsLoading(false);
    }
  };

  const fetchStats = useCallback(async () => {
    try {
      const res = await fetch("/api/stats");
      if (res.ok) {
        const data = await res.json();
        if (data.stats !== prevStatsRef.current) {
          prevStatsRef.current = data.stats;
          setStats(data);
        }
      }
    } catch (error) {
      console.error("Error fetching stats:", error);
    }
  }, []);

  useEffect(() => {
    const loadData = async () => {
      await fetchData();
    };
    loadData();
  }, []);

  useEffect(() => {
    fetchStats();
    const interval = setInterval(fetchStats, 5000);
    return () => clearInterval(interval);
  }, [fetchStats]);

